      /* Unified brand system: green is the only chromatic brand accent. */
      :root{--green:#0b9873;--green-dark:#087456;--violet:var(--green);--nav:#102b27;--nav-muted:#b4c9c2;--bg:#f7f9f8;--line:#e5ece8;--soft-shadow:0 4px 16px rgba(18,52,40,.045);--shadow:0 10px 28px rgba(18,52,40,.07)}
