<script>
function closeAppSidebar(){const s=document.getElementById('appSidebar'),b=document.getElementById('sidebarBackdrop'),t=document.querySelector('.menu-toggle');if(s)s.classList.remove('open');if(b)b.classList.remove('open');if(t){t.setAttribute('aria-expanded','false');t.setAttribute('aria-label','Open navigation')}}
function toggleAppSidebar(){const s=document.getElementById('appSidebar'),b=document.getElementById('sidebarBackdrop'),t=document.querySelector('.menu-toggle');if(!s)return;const open=!s.classList.contains('open');s.classList.toggle('open',open);if(b)b.classList.toggle('open',open);if(t){t.setAttribute('aria-expanded',String(open));t.setAttribute('aria-label',open?'Close navigation':'Open navigation')}}
const publicToggle=document.getElementById('publicMenuToggle'),publicNav=document.getElementById('publicNav');
if(publicToggle&&publicNav){publicToggle.addEventListener('click',()=>{const open=!publicNav.classList.contains('open');publicNav.classList.toggle('open',open);publicToggle.setAttribute('aria-expanded',String(open));publicToggle.setAttribute('aria-label',open?'Close menu':'Open menu');publicToggle.innerHTML=open?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="m6 6 12 12M18 6 6 18"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg>'});publicNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{publicNav.classList.remove('open');publicToggle.setAttribute('aria-expanded','false');publicToggle.setAttribute('aria-label','Open menu')}))}
document.addEventListener('click',function(event){const button=event.target.closest('[data-password-toggle]');if(!button)return;const input=document.getElementById(button.dataset.passwordToggle);if(!input)return;const reveal=input.type==='password';input.type=reveal?'text':'password';button.textContent=reveal?'Hide':'Show';button.setAttribute('aria-pressed',reveal?'true':'false')});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeAppSidebar();if(publicNav)publicNav.classList.remove('open');if(publicToggle){publicToggle.setAttribute('aria-expanded','false');publicToggle.setAttribute('aria-label','Open menu')}}});
if('serviceWorker'in navigator&&location.protocol==='https:'){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}))}
</script>
</body></html>